    for (r = 0; r < row_size; r++) {
        for (c = 0; c < col_size; c++) {
            diff = data->prod[r * row_size + c] - ref->prod[r * row_size + c];
            if ((diff < -EPSILON) || (EPSILON < diff)) {
                printf(
                    "Output data mismatch at index %d: (actual) %f != %f "
